#Requires -Version 7.2
[CmdletBinding()]
param(
  [ValidateSet('Plan','Verify')][string]$Action='Plan',
  [string]$PsqlPath,[string]$ExpectedPsqlSha256,[string]$ProjectRef,[ValidateSet('direct','session_pooler')][string]$ConnectionMode,
  [string]$DatabaseHost,[int]$DatabasePort=5432,[string]$DatabaseName,[string]$DatabaseSchema,
  [string]$CaCertificatePath,[string]$ExpectedCaCertificateSha256,
  [string]$RuntimeDatabaseUser,[string]$RuntimePgPassFile,[string]$ExpectedRuntimePgPassSha256,
  [string]$AdminDatabaseUser,[string]$AdminPgPassFile,[string]$ExpectedAdminPgPassSha256,
  [string]$MigrationDatabaseUser,[string]$MigrationPgPassFile,[string]$ExpectedMigrationPgPassSha256,
  [string]$BackupDatabaseUser,[string]$BackupPgPassFile,[string]$ExpectedBackupPgPassSha256,
  [string]$RestoreDatabaseUser,
  [string]$FileSystemEvidencePath,[string]$ExpectedFileSystemEvidenceSha256,[string]$EvidenceOutputPath,
  [ValidateRange(60,1800)][int]$MaximumVerificationDurationSeconds=600,[ValidateRange(1024,1048576)][int]$MaximumChildOutputBytes=1048576,
  [ValidateSet('VerifyEvidence')][string]$PlannedAction,[string]$ApprovedPlanSha256,[string]$ApprovalNonce,[string]$ApprovalIssuedAt,[string]$ApprovalExpiresAt,[string]$ApprovalInstanceId,[string]$ApprovalLedgerPath,[switch]$Approved
)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'approval-plan.ps1')

function Digest([string]$Value){$sha=[Security.Cryptography.SHA256]::Create();try{return([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($Value))).Replace('-','').ToLowerInvariant())}finally{$sha.Dispose()}}
function Identity([string]$Value,[string]$Code){if($Value-notmatch'^[a-z][a-z0-9_]{0,62}$'){throw $Code}}
function NoReparse([string]$Path){$cursor=Get-Item -LiteralPath ([IO.Path]::GetFullPath($Path)) -Force;while($cursor){if($cursor.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'DATABASE_BOUNDARY_REPARSE_REJECTED'};$cursor=$cursor.Parent}}
function Under([string]$Path,[string[]]$Roots){$full=[IO.Path]::GetFullPath($Path);return @($Roots|Where-Object{$root=[IO.Path]::GetFullPath([string]$_).TrimEnd('\');$full-ieq$root-or$full.StartsWith($root+'\',[StringComparison]::OrdinalIgnoreCase)}).Count-gt0}
function Assert-PsqlPinned(){if(-not(Test-Path -LiteralPath $PsqlPath -PathType Leaf)){throw 'PSQL_HASH_MISMATCH'};NoReparse $PsqlPath;if($ExpectedPsqlSha256-notmatch'^[A-Fa-f0-9]{64}$'-or(Get-FileHash -LiteralPath $PsqlPath -Algorithm SHA256).Hash-ine$ExpectedPsqlSha256){throw 'PSQL_HASH_MISMATCH'}}
function Stop-BoundaryProcessTree($Process){if($Process-and-not$Process.HasExited){try{$Process.Kill($true)}catch{throw 'DATABASE_BOUNDARY_PROCESS_TREE_KILL_FAILED'};if(-not$Process.WaitForExit(5000)){throw 'DATABASE_BOUNDARY_PROCESS_TREE_KILL_TIMEOUT'}}}
function Invoke-BoundaryChild([string[]]$Arguments,[hashtable]$Environment,[switch]$AllowFailure){
  Assert-PsqlPinned;if(-not$script:BoundaryWatch){throw 'DATABASE_BOUNDARY_DEADLINE_NOT_STARTED'};$remaining=[long]($MaximumVerificationDurationSeconds*1000-$script:BoundaryWatch.ElapsedMilliseconds);if($remaining-le0){throw 'DATABASE_BOUNDARY_DEADLINE_EXCEEDED'}
  $info=[Diagnostics.ProcessStartInfo]::new();$info.FileName=[IO.Path]::GetFullPath($PsqlPath);$info.UseShellExecute=$false;$info.CreateNoWindow=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;foreach($argument in $Arguments){$info.ArgumentList.Add($argument)};foreach($name in @('DATABASE_URL','PGPASSWORD','PGPASSFILE','PGSSLMODE','PGSSLROOTCERT','PGOPTIONS','PGCONNECT_TIMEOUT')){$info.Environment.Remove($name)|Out-Null};foreach($name in $Environment.Keys){$info.Environment[$name]=[string]$Environment[$name]}
  $process=[Diagnostics.Process]::new();$process.StartInfo=$info;$stdout=[IO.MemoryStream]::new();$stderr=[IO.MemoryStream]::new();$outBuffer=New-Object byte[] 8192;$errBuffer=New-Object byte[] 8192
  try{if(-not$process.Start()){throw 'DATABASE_BOUNDARY_PROCESS_START_FAILED'};$outTask=$process.StandardOutput.BaseStream.ReadAsync($outBuffer,0,$outBuffer.Length);$errTask=$process.StandardError.BaseStream.ReadAsync($errBuffer,0,$errBuffer.Length);$outDone=$false;$errDone=$false
    while(-not($process.HasExited-and$outDone-and$errDone)){if($script:BoundaryWatch.ElapsedMilliseconds-ge([long]$MaximumVerificationDurationSeconds*1000)){Stop-BoundaryProcessTree $process;throw 'DATABASE_BOUNDARY_PROCESS_TIMEOUT'};if(-not$outDone-and$outTask.IsCompleted){$count=$outTask.GetAwaiter().GetResult();if($count-eq0){$outDone=$true}else{if($stdout.Length+$stderr.Length+$count-gt$MaximumChildOutputBytes){Stop-BoundaryProcessTree $process;throw 'DATABASE_BOUNDARY_OUTPUT_LIMIT'};$stdout.Write($outBuffer,0,$count);$outTask=$process.StandardOutput.BaseStream.ReadAsync($outBuffer,0,$outBuffer.Length)}};if(-not$errDone-and$errTask.IsCompleted){$count=$errTask.GetAwaiter().GetResult();if($count-eq0){$errDone=$true}else{if($stdout.Length+$stderr.Length+$count-gt$MaximumChildOutputBytes){Stop-BoundaryProcessTree $process;throw 'DATABASE_BOUNDARY_OUTPUT_LIMIT'};$stderr.Write($errBuffer,0,$count);$errTask=$process.StandardError.BaseStream.ReadAsync($errBuffer,0,$errBuffer.Length)}};if(-not($process.HasExited-and$outDone-and$errDone)){[Threading.Thread]::Sleep(10)}}
    if($process.ExitCode-ne0-and-not$AllowFailure){throw 'DATABASE_QUERY_FAILED'};return [pscustomobject]@{ExitCode=$process.ExitCode;Output=[Text.Encoding]::UTF8.GetString($stdout.ToArray()).Trim()}
  }finally{Stop-BoundaryProcessTree $process;$process.Dispose();$stdout.Dispose();$stderr.Dispose()}
}
function Assert-SecretAcl([string]$Path,[string]$Class,$Fs){$acl=Get-Acl -LiteralPath $Path;$admin='S-1-5-32-544';$system='S-1-5-18';$expected=@($system,$admin);if($Class-eq'CORE_READ'){$expected+=[string]$Fs.coreServiceSid}elseif($Class-eq'BACKUP_ONLY'){$expected+=[string]$Fs.backupSid};$expected=@($expected|Sort-Object -Unique);if(-not$acl.AreAccessRulesProtected-or$acl.Owner.Translate([Security.Principal.SecurityIdentifier]).Value-ne$admin-or@($acl.Access).Count-ne$expected.Count){throw 'DATABASE_SECRET_ACL_INVALID'};$full=[Security.AccessControl.FileSystemRights]::FullControl;$read=[Security.AccessControl.FileSystemRights]'ReadAndExecute,Synchronize';foreach($rule in $acl.Access){$sid=$rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value;$rights=if($sid-in@($system,$admin)){$full}else{$read};if($sid-notin$expected-or$rule.AccessControlType-ne'Allow'-or$rule.FileSystemRights-ne$rights-or$rule.IsInherited){throw 'DATABASE_SECRET_ACL_INVALID'}}}
function ConnectionUser([string]$Role){if($ConnectionMode-eq'session_pooler'){return "$Role.$ProjectRef"};return $Role}
function PgCredential([string]$Path,[string]$ExpectedRole){$expectedUser=ConnectionUser $ExpectedRole;$lines=@(Get-Content -LiteralPath $Path|Where-Object{$_-and-not$_.StartsWith('#')});if($lines.Count-ne1){throw 'PGPASS_FORMAT_INVALID'};$parts=[Collections.Generic.List[string]]::new();$current=New-Object Text.StringBuilder;$escaped=$false;foreach($character in $lines[0].ToCharArray()){if($escaped){$current.Append($character)|Out-Null;$escaped=$false;continue};if($character-eq'\'){$escaped=$true;continue};if($character-eq':'-and$parts.Count-lt4){$parts.Add($current.ToString());$current.Clear()|Out-Null}else{$current.Append($character)|Out-Null}};if($escaped){throw 'PGPASS_FORMAT_INVALID'};$parts.Add($current.ToString());if($parts.Count-ne5-or$parts[0]-cne$DatabaseHost-or$parts[1]-ne'5432'-or$parts[2]-cne$DatabaseName-or$parts[3]-cne$expectedUser-or-not$parts[4]){throw 'PGPASS_FORMAT_INVALID'};return [pscustomobject]@{Role=$ExpectedRole;ConnectionUser=$expectedUser;Password=$parts[4]}}
function PsqlArgs([string]$User,[string]$Sql){return @("--host=$DatabaseHost",'--port=5432',"--username=$User","--dbname=$DatabaseName",'--no-password','--tuples-only','--no-align','--set=ON_ERROR_STOP=1',"--set=sslmode=verify-full","--command=$Sql")}
function Invoke-Psql([string]$Role,[string]$PassFile,[string]$Sql){$environment=@{PGPASSFILE=[IO.Path]::GetFullPath($PassFile);PGSSLMODE='verify-full';PGSSLROOTCERT=[IO.Path]::GetFullPath($CaCertificatePath);PGCONNECT_TIMEOUT='15';PGOPTIONS="-c search_path=$DatabaseSchema -c lock_timeout=10000 -c statement_timeout=60000 -c idle_in_transaction_session_timeout=30000"};return (Invoke-BoundaryChild (PsqlArgs (ConnectionUser $Role) $Sql) $environment).Output}
function Test-Password([string]$ConnectionUser,[string]$Password,[string]$SslMode='verify-full'){$environment=@{PGPASSWORD=$Password;PGSSLMODE=$SslMode;PGCONNECT_TIMEOUT='15';PGOPTIONS='-c lock_timeout=10000 -c statement_timeout=60000 -c idle_in_transaction_session_timeout=30000'};if($SslMode-eq'verify-full'){$environment.PGSSLROOTCERT=[IO.Path]::GetFullPath($CaCertificatePath)};$result=Invoke-BoundaryChild @("--host=$DatabaseHost",'--port=5432',"--username=$ConnectionUser","--dbname=$DatabaseName",'--no-password','--tuples-only','--no-align','--set=ON_ERROR_STOP=1','--command=SELECT 1') $environment -AllowFailure;return $result.ExitCode-eq0}
function PublicAddress([Net.IPAddress]$Address){if([Net.IPAddress]::IsLoopback($Address)){return $false};if($Address.AddressFamily-eq[Net.Sockets.AddressFamily]::InterNetwork){$b=$Address.GetAddressBytes();return-not($b[0]-eq10-or($b[0]-eq172-and$b[1]-ge16-and$b[1]-le31)-or($b[0]-eq192-and$b[1]-eq168)-or$b[0]-eq127-or($b[0]-eq169-and$b[1]-eq254)-or$b[0]-ge224)};$bytes=$Address.GetAddressBytes();return-not($Address.IsIPv6LinkLocal-or$Address.IsIPv6SiteLocal-or($bytes[0]-band0xfe)-eq0xfc-or$bytes[0]-eq0xff)}

function New-DatabaseBoundaryApprovalPlan([string]$IntendedAction){
  if($IntendedAction-cne'VerifyEvidence'){throw 'DATABASE_BOUNDARY_PLAN_ACTION_REQUIRED'}
  $p=[ordered]@{psqlPath=Get-ApprovalPath $PsqlPath 'DATABASE_BOUNDARY_PLAN_PSQL_PATH_REQUIRED';psqlSha256=Get-ApprovalHash $ExpectedPsqlSha256 'DATABASE_BOUNDARY_PLAN_PSQL_HASH_REQUIRED';projectRef=Get-ApprovalText $ProjectRef '^[a-z]{20}$' 'DATABASE_BOUNDARY_PLAN_PROJECT_REQUIRED';connectionMode=$ConnectionMode;databaseHost=Get-ApprovalText $DatabaseHost '^([a-z0-9-]+\.)+supabase\.(co|com)$' 'DATABASE_BOUNDARY_PLAN_HOST_REQUIRED';databasePort=$DatabasePort;databaseName=$DatabaseName;databaseSchema=$DatabaseSchema;caCertificatePath=Get-ApprovalPath $CaCertificatePath 'DATABASE_BOUNDARY_PLAN_CA_PATH_REQUIRED';caCertificateSha256=Get-ApprovalHash $ExpectedCaCertificateSha256 'DATABASE_BOUNDARY_PLAN_CA_HASH_REQUIRED';runtimeDatabaseUser=$RuntimeDatabaseUser;runtimePgPassFile=Get-ApprovalPath $RuntimePgPassFile 'DATABASE_BOUNDARY_PLAN_RUNTIME_PGPASS_REQUIRED';runtimePgPassSha256=Get-ApprovalHash $ExpectedRuntimePgPassSha256 'DATABASE_BOUNDARY_PLAN_RUNTIME_PGPASS_HASH_REQUIRED';adminDatabaseUser=$AdminDatabaseUser;adminPgPassFile=Get-ApprovalPath $AdminPgPassFile 'DATABASE_BOUNDARY_PLAN_ADMIN_PGPASS_REQUIRED';adminPgPassSha256=Get-ApprovalHash $ExpectedAdminPgPassSha256 'DATABASE_BOUNDARY_PLAN_ADMIN_PGPASS_HASH_REQUIRED';migrationDatabaseUser=$MigrationDatabaseUser;migrationPgPassFile=Get-ApprovalPath $MigrationPgPassFile 'DATABASE_BOUNDARY_PLAN_MIGRATION_PGPASS_REQUIRED';migrationPgPassSha256=Get-ApprovalHash $ExpectedMigrationPgPassSha256 'DATABASE_BOUNDARY_PLAN_MIGRATION_PGPASS_HASH_REQUIRED';backupDatabaseUser=$BackupDatabaseUser;backupPgPassFile=Get-ApprovalPath $BackupPgPassFile 'DATABASE_BOUNDARY_PLAN_BACKUP_PGPASS_REQUIRED';backupPgPassSha256=Get-ApprovalHash $ExpectedBackupPgPassSha256 'DATABASE_BOUNDARY_PLAN_BACKUP_PGPASS_HASH_REQUIRED';restoreDatabaseUser=$RestoreDatabaseUser;filesystemEvidencePath=Get-ApprovalPath $FileSystemEvidencePath 'DATABASE_BOUNDARY_PLAN_FS_PATH_REQUIRED';filesystemEvidenceSha256=Get-ApprovalHash $ExpectedFileSystemEvidenceSha256 'DATABASE_BOUNDARY_PLAN_FS_HASH_REQUIRED';evidenceOutputPath=Get-ApprovalPath $EvidenceOutputPath 'DATABASE_BOUNDARY_PLAN_OUTPUT_REQUIRED';maximumVerificationDurationSeconds=$MaximumVerificationDurationSeconds;maximumChildOutputBytes=$MaximumChildOutputBytes}
  New-ApprovalPlan $PSCommandPath 'VerifyEvidence' $p "Existing exact Supabase PostgreSQL project $ProjectRef, host $DatabaseHost, database/schema $DatabaseName/$DatabaseSchema" 'Runs read-only TLS/session/catalog/least-privilege checks using hash-pinned credential files and writes one non-secret boundary receipt' 'Delete only the exact evidence file; this action never changes the database'
}

if($Action-eq'Plan'){New-DatabaseBoundaryApprovalPlan $PlannedAction|ConvertTo-Json -Depth 12;exit 0}
if($EvidenceOutputPath){$approvalPlan=New-DatabaseBoundaryApprovalPlan 'VerifyEvidence';Assert-ApprovedPlan $approvalPlan ([bool]$Approved) $ApprovedPlanSha256}
$script:BoundaryWatch=[Diagnostics.Stopwatch]::StartNew()
if($ProjectRef-notmatch'^[a-z]{20}$'-or$DatabasePort-ne5432){throw 'SUPABASE_DATABASE_TARGET_INVALID'}
if($ConnectionMode-eq'direct' -and $DatabaseHost-cne"db.$ProjectRef.supabase.co"){throw 'SUPABASE_DATABASE_HOST_INVALID'}
if($ConnectionMode-eq'session_pooler' -and $DatabaseHost-notmatch'^[a-z0-9-]+\.pooler\.supabase\.com$'){throw 'SUPABASE_DATABASE_HOST_INVALID'}
foreach($identity in @($DatabaseName,$DatabaseSchema,$RuntimeDatabaseUser,$AdminDatabaseUser,$MigrationDatabaseUser,$BackupDatabaseUser,$RestoreDatabaseUser)){Identity $identity 'DATABASE_IDENTITY_INVALID'}
if(@(@($RuntimeDatabaseUser,$AdminDatabaseUser,$MigrationDatabaseUser,$BackupDatabaseUser,$RestoreDatabaseUser)|Sort-Object -Unique).Count-ne5){throw 'DATABASE_ROLES_MUST_BE_DISTINCT'}
foreach($file in @($PsqlPath,$CaCertificatePath,$RuntimePgPassFile,$AdminPgPassFile,$MigrationPgPassFile,$BackupPgPassFile,$FileSystemEvidencePath)){if(-not(Test-Path -LiteralPath $file -PathType Leaf)){throw 'DATABASE_BOUNDARY_FILE_NOT_FOUND'};NoReparse $file}
Assert-PsqlPinned
if($ExpectedCaCertificateSha256-notmatch'^[A-Fa-f0-9]{64}$'-or(Get-FileHash -LiteralPath $CaCertificatePath -Algorithm SHA256).Hash-ine$ExpectedCaCertificateSha256){throw 'DATABASE_CA_HASH_MISMATCH'}
foreach($entry in @(@{Path=$RuntimePgPassFile;Expected=$ExpectedRuntimePgPassSha256},@{Path=$AdminPgPassFile;Expected=$ExpectedAdminPgPassSha256},@{Path=$MigrationPgPassFile;Expected=$ExpectedMigrationPgPassSha256},@{Path=$BackupPgPassFile;Expected=$ExpectedBackupPgPassSha256},@{Path=$FileSystemEvidencePath;Expected=$ExpectedFileSystemEvidenceSha256})){if($entry.Expected-notmatch'^[A-Fa-f0-9]{64}$'-or(Get-FileHash -LiteralPath $entry.Path -Algorithm SHA256).Hash-ine$entry.Expected){throw 'DATABASE_BOUNDARY_INPUT_HASH_MISMATCH'}}
$addresses=@([Net.Dns]::GetHostAddresses($DatabaseHost));if($addresses.Count-eq0-or$addresses|Where-Object{-not(PublicAddress $_)}){throw 'DATABASE_DNS_BOUNDARY_FAILED'}
$fs=Get-Content -Raw -LiteralPath $FileSystemEvidencePath|ConvertFrom-Json;if($fs.result-ne'PASS'-or-not$fs.exactAcl-or-not(Under $PsqlPath $fs.classRoots.SHARED_RUNTIME)){throw 'FILESYSTEM_EVIDENCE_REJECTED'}
foreach($entry in @(@{Path=$RuntimePgPassFile;Class='CORE_READ'},@{Path=$AdminPgPassFile;Class='ADMIN_ONLY'},@{Path=$MigrationPgPassFile;Class='ADMIN_ONLY'},@{Path=$BackupPgPassFile;Class='BACKUP_ONLY'})){$class=[string]$entry.Class;if(-not(Under $entry.Path $fs.classRoots.$class)){throw 'DATABASE_SECRET_CLASS_REJECTED'};Assert-SecretAcl $entry.Path $class $fs}
$credentials=@((PgCredential $RuntimePgPassFile $RuntimeDatabaseUser),(PgCredential $AdminPgPassFile $AdminDatabaseUser),(PgCredential $MigrationPgPassFile $MigrationDatabaseUser),(PgCredential $BackupPgPassFile $BackupDatabaseUser))
if(@($credentials.Password|Sort-Object -Unique).Count-ne4){throw 'DATABASE_CREDENTIAL_REUSE_DETECTED'}
foreach($source in $credentials){if(-not(Test-Password $source.ConnectionUser $source.Password)){throw 'DATABASE_SELF_AUTH_FAILED'};foreach($target in $credentials){if($source.Role-cne$target.Role-and(Test-Password $target.ConnectionUser $source.Password)){throw 'DATABASE_CROSS_ROLE_AUTH_SUCCEEDED'}}}
if(Test-Password $credentials[0].ConnectionUser $credentials[0].Password 'disable'){throw 'DATABASE_SSL_ENFORCEMENT_DISABLED'}
$identity=Invoke-Psql $RuntimeDatabaseUser $RuntimePgPassFile 'SELECT current_user || ''|'' || current_database() || ''|'' || current_schema()';if($identity-ne"$RuntimeDatabaseUser|$DatabaseName|$DatabaseSchema"){throw 'DATABASE_RUNTIME_IDENTITY_FAILED'}
$tls=Invoke-Psql $RuntimeDatabaseUser $RuntimePgPassFile "SELECT ssl || '|' || version || '|' || cipher FROM pg_stat_ssl WHERE pid=pg_backend_pid()";$tlsParts=$tls.Split('|');if($tlsParts.Count-ne3-or$tlsParts[0]-ne't'-or$tlsParts[1]-notin@('TLSv1.2','TLSv1.3')-or-not$tlsParts[2]){throw 'DATABASE_TLS_SESSION_FAILED'}
$runtimeFlags=Invoke-Psql $RuntimeDatabaseUser $RuntimePgPassFile 'SELECT rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls FROM pg_roles WHERE rolname=current_user';if($runtimeFlags-ne't'){throw 'DATABASE_RUNTIME_ROLE_ATTRIBUTES_INVALID'}
$ddl=Invoke-Psql $RuntimeDatabaseUser $RuntimePgPassFile "SELECT NOT has_database_privilege(current_user,current_database(),'CREATE') AND NOT has_schema_privilege(current_user,'$DatabaseSchema','CREATE')";if($ddl-ne't'){throw 'DATABASE_RUNTIME_DDL_PRIVILEGE_PRESENT'}
$roleList=@($RuntimeDatabaseUser,$MigrationDatabaseUser,$BackupDatabaseUser);$roleLiterals=($roleList|ForEach-Object{"'$_'"})-join','
$roleProof=Invoke-Psql $AdminDatabaseUser $AdminPgPassFile "SELECT count(*) FROM pg_roles WHERE rolname IN ($roleLiterals) AND rolcanlogin AND NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole AND NOT rolreplication AND NOT rolbypassrls AND rolconnlimit BETWEEN 1 AND 20";if($roleProof-ne'3'){throw 'DATABASE_ROLE_BOUNDARY_FAILED'}
$scramProof=Invoke-Psql $AdminDatabaseUser $AdminPgPassFile "SELECT count(*) FROM pg_authid WHERE rolname IN ($roleLiterals) AND rolpassword LIKE 'SCRAM-SHA-256`$%'";if($scramProof-ne'3'){throw 'DATABASE_ROLE_SCRAM_REQUIRED'}
$restoreIsolationSql=@"
WITH restore_role AS (SELECT oid FROM pg_roles WHERE rolname='$RestoreDatabaseUser')
SELECT
  EXISTS(SELECT 1 FROM pg_roles r WHERE r.rolname='$RestoreDatabaseUser' AND r.rolcanlogin AND NOT r.rolsuper AND NOT r.rolcreatedb AND NOT r.rolcreaterole AND NOT r.rolreplication AND NOT r.rolbypassrls AND r.rolconnlimit BETWEEN 1 AND 4)
  AND NOT EXISTS(SELECT 1 FROM pg_database d,restore_role r WHERE d.datname='$DatabaseName' AND d.datdba=r.oid)
  AND NOT has_database_privilege('$RestoreDatabaseUser','$DatabaseName','CONNECT')
  AND NOT has_database_privilege('$RestoreDatabaseUser','$DatabaseName','CREATE')
  AND NOT has_database_privilege('$RestoreDatabaseUser','$DatabaseName','TEMP')
  AND NOT has_schema_privilege('$RestoreDatabaseUser','$DatabaseSchema','USAGE')
  AND NOT has_schema_privilege('$RestoreDatabaseUser','$DatabaseSchema','CREATE')
  AND NOT EXISTS(SELECT 1 FROM pg_auth_members m,restore_role r WHERE m.member=r.oid OR m.roleid=r.oid)
  AND NOT EXISTS(SELECT 1 FROM pg_namespace n,restore_role r WHERE n.nspname='$DatabaseSchema' AND n.nspowner=r.oid)
  AND NOT EXISTS(
    SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace,restore_role r
    WHERE n.nspname='$DatabaseSchema' AND (
      c.relowner=r.oid OR
      (c.relkind IN ('r','p','v','m','f') AND (has_table_privilege('$RestoreDatabaseUser',c.oid,'SELECT') OR has_table_privilege('$RestoreDatabaseUser',c.oid,'INSERT') OR has_table_privilege('$RestoreDatabaseUser',c.oid,'UPDATE') OR has_table_privilege('$RestoreDatabaseUser',c.oid,'DELETE') OR has_table_privilege('$RestoreDatabaseUser',c.oid,'TRUNCATE') OR has_table_privilege('$RestoreDatabaseUser',c.oid,'REFERENCES') OR has_table_privilege('$RestoreDatabaseUser',c.oid,'TRIGGER'))) OR
      (c.relkind='S' AND (has_sequence_privilege('$RestoreDatabaseUser',c.oid,'USAGE') OR has_sequence_privilege('$RestoreDatabaseUser',c.oid,'SELECT') OR has_sequence_privilege('$RestoreDatabaseUser',c.oid,'UPDATE')))
    )
  )
  AND NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace,restore_role r WHERE n.nspname='$DatabaseSchema' AND (p.proowner=r.oid OR has_function_privilege('$RestoreDatabaseUser',p.oid,'EXECUTE')))
  AND NOT EXISTS(SELECT 1 FROM pg_type t JOIN pg_namespace n ON n.oid=t.typnamespace,restore_role r WHERE n.nspname='$DatabaseSchema' AND (t.typowner=r.oid OR has_type_privilege('$RestoreDatabaseUser',t.oid,'USAGE')))
  AND NOT EXISTS(SELECT 1 FROM pg_default_acl d CROSS JOIN LATERAL aclexplode(COALESCE(d.defaclacl,'{}'::aclitem[])) x,restore_role r WHERE d.defaclrole=r.oid OR x.grantee=r.oid)
"@
$restoreIsolationProof=Invoke-Psql $AdminDatabaseUser $AdminPgPassFile $restoreIsolationSql;if($restoreIsolationProof-ne't'){throw 'PRODUCTION_RESTORE_ROLE_ACCESS_PRESENT'}
$restoreAbsent=$restoreIsolationProof
$membershipProof=Invoke-Psql $AdminDatabaseUser $AdminPgPassFile "SELECT count(*) FROM pg_auth_members m JOIN pg_roles member_role ON member_role.oid=m.member JOIN pg_roles granted_role ON granted_role.oid=m.roleid WHERE member_role.rolname IN ($roleLiterals) OR granted_role.rolname IN ($roleLiterals)";if($membershipProof-ne'0'){throw 'DATABASE_ROLE_MEMBERSHIP_PRESENT'}
